package com.ansh.bank.support.service;
import java.time.*; import java.util.*; import com.ansh.bank.common.config.SeedData; import com.ansh.bank.support.dto.SupportDtos.*; import org.springframework.stereotype.Service;
/** Create and retrieve customer support tickets. */ @Service public class SupportService {private final SeedData d; public SupportService(SeedData d){this.d=d;} /** List submitted tickets. */ public List<Response> all(){return d.tickets.stream().map(this::map).toList();} /** File a new ticket. */ public Response add(CreateRequest r){var t=new SeedData.Ticket("ticket-"+UUID.randomUUID(),r.subject(),r.message(),"OPEN",LocalDateTime.now());d.tickets.add(0,t);return map(t);} private Response map(SeedData.Ticket t){return new Response(t.id(),t.subject(),t.message(),t.status(),t.createdAt());} }
